(() => {
'use strict';
const R=window.CookXuanReading,D=window.COOKXUAN_CATALOG,recipe=D.recipes.find(r=>r.id===R.example),params=new URLSearchParams(location.search);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg aria-hidden="true"><use href="#${name}"/></svg>`;
const cover='../'+recipe.cover,hero='../assets/hero.webp.webp';
const selected=['a','b','c'].includes(params.get('style'))?params.get('style'):null;
let screen=params.get('screen')==='home'?'home':'cook',mobileStyle=selected||'b';
const states=Object.fromEntries(['a','b','c'].map(style=>[style,{stage:0,item:0,checks:new Set()}]));
document.body.classList.add('show-'+mobileStyle);if(selected)document.body.classList.add('single','style-'+selected);
function stepHeader(style,state){return `<header class="phone-header"><button class="round-button" data-action="home" data-style="${style}" aria-label="回到首页">${icon('back')}</button><strong>${style==='b'?'CookXuan · 厨房手册':recipe.name}</strong><span class="phone-count">${Math.min(state.stage+1,recipe.steps.length)} / ${recipe.steps.length}</span></header>`;}
function done(style){return `${stepHeader(style,states[style])}<div class="phone-content"><div class="food-photo" style="height:200px"> <img src="${cover}" alt="${recipe.name}"></div><section class="focus-done">${icon('check')}<h2>这一餐，做成了。</h2><p>${recipe.name}</p><button class="primary" data-action="restart" data-style="${style}">重新体验 ${icon('arrow')}</button></section></div><footer class="phone-footer"><button class="secondary" data-action="home" data-style="${style}">回到首页</button><a class="primary" href="../index.html#library">再选一道菜 ${icon('arrow')}</a></footer>`;}
function renderChecklist(style){const s=states[style],actions=R.actionsFor(recipe,s.stage),stage=R.headingFor(recipe,s.stage);return `${stepHeader(style,s)}<div class="check-progress"><span style="width:${s.checks.size/actions.length*100}%"></span></div><div class="phone-content"><div class="food-photo"><img src="${cover}" alt="${recipe.name}"></div><div class="stage-label">第 ${s.stage+1} 步<span class="sep">·</span>${s.stage===0?'备菜':'下锅'}</div><h2 class="stage-title">${stage}</h2><ol class="task-list">${actions.map((a,i)=>`<li class="task"><label><input type="checkbox" data-task="${i}" data-style="${style}" aria-label="完成${esc(a.title||'第 '+(i+1)+' 项动作')}" ${s.checks.has(i)?'checked':''}><span class="task-box" aria-hidden="true">${icon('check')}</span><span class="task-text">${a.title?`<strong>${esc(a.title)}</strong>`:''}<p class="${a.title?'':'only-text'}">${esc(a.body)}</p></span></label></li>`).join('')}</ol><div class="counter-line"><span class="completed-count" aria-live="polite">已完成 ${s.checks.size} / ${actions.length} 项</span><button data-action="reset-checks" data-style="${style}">重置勾选</button></div></div><footer class="phone-footer"><button class="secondary" data-action="prev" data-style="${style}" ${s.stage===0?'disabled':''}>上一步</button><button class="primary" data-action="next" data-style="${style}">${s.stage===0?'备好了，下一步':s.stage===recipe.steps.length-1?'开饭啦':'下一步'}${icon('arrow')}</button></footer>`;}
function renderNotebook(style){const s=states[style],actions=R.actionsFor(recipe,s.stage);return `${stepHeader(style,s)}<div class="phone-content"><header class="notebook-title"><div><h2>${recipe.name}</h2><p>家常小炒 · 17 分钟</p></div><img src="${cover}" alt="${recipe.name}"></header><div class="stage-label">${String(s.stage+1).padStart(2,'0')} / ${String(recipe.steps.length).padStart(2,'0')}</div><h2 class="stage-title">${R.headingFor(recipe,s.stage)}</h2><ol class="notebook-list">${actions.map((a,i)=>`<li class="notebook-item"><span class="notebook-number">${String(i+1).padStart(2,'0')}</span><div>${a.title?`<strong>${esc(a.title)}</strong>`:''}<p>${esc(a.body)}</p></div></li>`).join('')}</ol></div><footer class="phone-footer"><button class="secondary" data-action="prev" data-style="${style}" ${s.stage===0?'disabled':''}>上一页</button><button class="primary" data-action="next" data-style="${style}">${s.stage===0?'备好，开始炒':'继续做下一步'}${icon('arrow')}</button></footer>`;}
function renderFocus(style){const s=states[style],actions=R.actionsFor(recipe,s.stage),a=actions[s.item],next=actions[s.item+1];return `${stepHeader(style,s)}<div class="phone-content"><div class="focus-image"><img src="${cover}" alt="${recipe.name}"></div><div class="action-dots" role="group" aria-label="选择当前动作">${actions.map((_,i)=>`<button class="${i===s.item?'active':i<s.item?'done':''}" data-jump="${i}" data-style="${style}" aria-label="动作 ${i+1}" aria-pressed="${i===s.item}"></button>`).join('')}</div><p class="focus-position">${s.stage===0?'备菜':'第 '+(s.stage+1)+' 步'} · ${s.item+1} / ${actions.length}</p><h2 class="focus-title">${esc(a.title||R.headingFor(recipe,s.stage))}</h2><p class="focus-copy">${esc(a.body)}</p><p class="focus-up-next">接下来<span>${esc(next?.title||next?.body||R.headingFor(recipe,s.stage+1)||'盛盘，开饭')}</span></p></div><footer class="phone-footer"><button class="secondary" data-action="prev" data-style="${style}" ${s.stage===0&&s.item===0?'disabled':''}>上一项</button><button class="primary" data-action="next" data-style="${style}">${s.item<actions.length-1?'做好了，下一项':s.stage===recipe.steps.length-1?'开饭啦':'这一项完成了'}${icon('arrow')}</button></footer>`;}
function home(style){const greeting=style==='b'?'好好吃饭，自有章法。':style==='c'?'这一餐，慢慢来。':'今天，吃好一点。';return `<header class="phone-header home-header"><a class="home-logo" href="./">Cook<span>Xuan</span></a><button class="round-button" data-action="cook" data-style="${style}" aria-label="进入做菜">${icon('book')}</button></header><div class="phone-content"><h2 class="home-greeting">${greeting}</h2><button class="home-cover" data-action="cook" data-style="${style}"><img src="${cover}" alt="农家一碗香"><span class="home-cover-copy"><p>今晚做一道家常菜</p><h3>农家一碗香</h3></span></button><section class="home-fridge"><h3>${style==='b'?'从手边的食材开始':'冰箱里有'}</h3><div class="chips"><span>猪肉</span><span>鸡蛋</span><span>青椒</span></div><button class="primary" data-action="cook" data-style="${style}">${style==='c'?'就做这道':'用这些做一餐'}${icon('arrow')}</button></section>${style==='c'?'':`<h3 class="home-list-title">再学一道拿手菜</h3><a class="home-feature" href="../index.html#recipe/tomato-noodles"><img src="${hero}" alt="番茄鸡蛋面"><strong>番茄鸡蛋暖心面</strong>${icon('arrow')}</a>`}</div><nav class="home-bottom" aria-label="${style.toUpperCase()} 原型导航"><button class="active" data-action="home" data-style="${style}">${icon('home')}开饭</button><a href="../index.html#pantry">${icon('fridge')}冰箱</a><a href="../index.html#library">${icon('book')}菜谱</a><a href="../index.html#me">${icon('heart')}我的</a></nav>`;}
function render(style){const el=document.getElementById('phone-'+style),s=states[style];el.innerHTML=screen==='home'?home(style):s.stage>=recipe.steps.length?done(style):style==='a'?renderChecklist(style):style==='b'?renderNotebook(style):renderFocus(style);}
function renderAll(){['a','b','c'].forEach(render);document.querySelectorAll('[data-screen]').forEach(b=>{b.classList.toggle('active',b.dataset.screen===screen);b.setAttribute('aria-pressed',b.dataset.screen===screen);});}
function advance(style,dir){const s=states[style];if(style==='c'){if(dir>0&&s.item<R.actionsFor(recipe,s.stage).length-1){s.item++;}else if(dir<0&&s.item>0){s.item--;}else{s.stage=Math.max(0,s.stage+dir);s.item=dir<0?R.actionsFor(recipe,s.stage).length-1:0;}}else{s.stage=Math.max(0,s.stage+dir);s.item=0;}s.checks.clear();render(style);}
document.addEventListener('click',event=>{
 const b=event.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.screen){screen=b.dataset.screen;renderAll();return;}
 if(b.dataset.show){document.body.classList.remove('show-'+mobileStyle);mobileStyle=b.dataset.show;document.body.classList.add('show-'+mobileStyle);document.querySelectorAll('[data-show]').forEach(el=>el.classList.toggle('active',el.dataset.show===mobileStyle));return;}
 const style=b.dataset.style;if(!states[style])return;
 if(b.dataset.jump!==undefined){states[style].item=+b.dataset.jump;render(style);return;}
 if(b.dataset.action==='next'){advance(style,1);return;}if(b.dataset.action==='prev'){advance(style,-1);return;}
 if(b.dataset.action==='home'){screen='home';renderAll();return;}
 if(b.dataset.action==='cook'||b.dataset.action==='restart'){screen='cook';states[style]={stage:0,item:0,checks:new Set()};renderAll();return;}
 if(b.dataset.action==='reset-checks'){states[style].checks.clear();render(style);}
});
document.addEventListener('change',event=>{const input=event.target;if(input.dataset.task===undefined)return;const style=input.dataset.style,index=+input.dataset.task,s=states[style];if(input.checked)s.checks.add(index);else s.checks.delete(index);const phone=document.getElementById('phone-'+style),total=R.actionsFor(recipe,s.stage).length;phone.querySelector('.completed-count').textContent=`已完成 ${s.checks.size} / ${total} 项`;phone.querySelector('.check-progress>span').style.width=s.checks.size/total*100+'%';});
document.querySelectorAll('[data-show]').forEach(el=>{el.classList.toggle('active',el.dataset.show===mobileStyle);el.setAttribute('aria-pressed',el.dataset.show===mobileStyle);});
renderAll();
})();
